import { type TinyMCEEditor } from '@divi/types';
/**
 * Gets the wrapper tag of the inline editor.
 *
 * This function retrieves the HTML tag of the wrapper element of the rich text editor.
 *
 * @since
 *
 * @example
 *
 * Example 1: Single tag check
 *
 * ```ts
 * import tinymce from 'tinymce';
 *
 * const tinymceEditorId = window.divi.data.select('divi/module').getInlineEditorToolbar().tinymceEditorId;
 * const editorInstance = tinymce.get(tinymceEditorId);
 *
 * const wrapperTag = getWrapperTag({
 *   tag: 'div',
 *   tinymceEditor: editorInstance,
 * });
 * // Returns 'div' if the editor's active parent tag is 'div', otherwise returns false.
 * ```
 *
 * @example
 *
 * Example 2: Multiple tag check
 *
 * ```ts
 * import tinymce from 'tinymce';
 *
 * const tinymceEditorId = window.divi.data.select('divi/module').getInlineEditorToolbar().tinymceEditorId;
 * const editorInstance = tinymce.get(tinymceEditorId);
 *
 * const wrapperTag = getWrapperTag({
 *   tag: ['div', 'p', 'section'],
 *   tinymceEditor: editorInstance,
 * });
 * // Returns the first matching tag from the editor's active parent tags array,
 * // if any of the provided tags are present, otherwise returns false.
 * ```
 *
 * @example
 *
 * Example 3: Invalid wrapper tag
 *
 * ```ts
 * import tinymce from 'tinymce';
 *
 * const tinymceEditorId = window.divi.data.select('divi/module').getInlineEditorToolbar().tinymceEditorId;
 * const editorInstance = tinymce.get(tinymceEditorId);
 *
 * const wrapperTag = getWrapperTag({
 *   tag: 'span',
 *   tinymceEditor: editorInstance,
 * });
 * // Returns false as the editor's active parent tag is not 'span'.
 * ```
 */
declare const getWrapperTag: ({ tag, tinymceEditor, }: {
    tag: string | string[];
    tinymceEditor: TinyMCEEditor;
}) => false | string;
export { getWrapperTag, };
